package com.example.acres.service; import com.example.acres.entity.User; import com.example.acres.repository.UserRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; @Service public class CurrentUserService {private final UserRepository repo; public CurrentUserService(UserRepository r){repo=r;} public User get(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return repo.findByEmailIgnoreCase(email).orElseThrow();}}
